package template

import (
	"fmt"
	"path/filepath"
	"sort"
)

// BlockWiring is the wiring one scaffold record declares for its block:
// an optional topic and the named ports in the block kind's order (From
// before To for transactional blocks). The cross-component checks —
// duplicate ports, conflicting topic contracts — belong to system
// assembly; this is one record's view.
type BlockWiring struct {
	// Topic is nil for kinds without one.
	Topic *TopicKey
	// Contract is the C# contract type Topic's messages carry, valid only
	// when Topic is non-nil.
	Contract string
	// Ports carries the named ports in the kind's order. A topic block
	// with no port in its record (MissingPort) has none.
	Ports []string
	// MissingPort marks a topic-block record without a port value, so the
	// caller can warn without failing the record.
	MissingPort bool
}

// TopicKey identifies a topic within a system: the pub/sub component it
// lives on plus the topic name. Two records naming the same key declare
// the two halves of one contract.
type TopicKey struct {
	Pubsub string
	Name   string
}

// BlockParser reads one scaffold record's values into its block wiring.
// The parser owns per-record validation only; cross-component checks stay
// with the caller.
type BlockParser func(values map[string]any, recordPath string) (BlockWiring, error)

// BlockParsers is the set of block kinds system assembly accepts — the
// same registry `int adopt` validates new records against, so a record
// either passes everywhere or nowhere. Adding a kind is a constant, a
// parser, and an entry here.
var BlockParsers = map[string]BlockParser{
	BlockKindExtractor:     ParseTopicBlock,
	BlockKindLoader:        ParseTopicBlock,
	BlockKindTransactional: ParseTransactionalBlock,
}

// SupportedBlockKinds lists the registry keys sorted, for error messages.
func SupportedBlockKinds() []string {
	kinds := make([]string, 0, len(BlockParsers))
	for k := range BlockParsers {
		kinds = append(kinds, k)
	}
	sort.Strings(kinds)
	return kinds
}

// ValidateBlockRecord runs the parser registry entry for kind against
// values, exactly as system assembly will when it later reads the record.
// It returns an error for a kind absent from the registry or for any
// missing or malformed required value; recordPath names the record in
// those errors (a synthetic path like ".intropy/scaffold.json" is fine
// for a record not yet written).
func ValidateBlockRecord(kind string, values map[string]any, recordPath string) error {
	parse, ok := BlockParsers[kind]
	if !ok {
		return fmt.Errorf("unsupported block kind %q (sys create assembles %s)", kind, joinKinds())
	}
	_, err := parse(values, recordPath)
	return err
}

func joinKinds() string {
	kinds := SupportedBlockKinds()
	out := ""
	for i, k := range kinds {
		if i > 0 {
			out += ", "
		}
		out += k
	}
	return out
}

// ParseTopicBlock parses the wiring of a topic block (extractor, loader):
// a required topic and contract, and one optional port. A record without a
// port stays a valid component — it just gets no From/To in the generated
// wiring.
func ParseTopicBlock(values map[string]any, recordPath string) (BlockWiring, error) {
	var w BlockWiring
	topic, err := StringValue(values, recordPath, "topic")
	if err != nil {
		return w, err
	}
	contract, err := StringValue(values, recordPath, "contract")
	if err != nil {
		return w, fmt.Errorf("%w\nRe-scaffold this integration with a template release that records the contract type, or add \"contract\": \"<TypeName>\" to the record's values.", err)
	}
	pubsub, err := StringValueDefault(values, recordPath, "pubsub", "pubsub")
	if err != nil {
		return w, err
	}
	w.Topic = &TopicKey{Pubsub: pubsub, Name: topic}
	w.Contract = contract

	// No fallback for the port: a default would describe a binding the
	// rendered code doesn't use. A missing key is reported by the caller as
	// a warning; a present one must be a non-empty string.
	if _, ok := values["port"]; ok {
		port, err := StringValue(values, recordPath, "port")
		if err != nil {
			return w, err
		}
		w.Ports = []string{port}
	} else {
		w.MissingPort = true
	}
	return w, nil
}

// ParseTransactionalBlock parses the wiring of a transactional block:
// exactly two ports, From before To, and no topic. Both ports are required
// — a half-wired transactional block would render broken code.
func ParseTransactionalBlock(values map[string]any, recordPath string) (BlockWiring, error) {
	var w BlockWiring
	from, err := StringValue(values, recordPath, "fromPort")
	if err != nil {
		return w, err
	}
	to, err := StringValue(values, recordPath, "toPort")
	if err != nil {
		return w, err
	}
	w.Ports = []string{from, to}
	return w, nil
}

// StringValue returns values[key] as a non-empty string, with errors that
// name the record so the user knows which project to fix.
func StringValue(values map[string]any, recordPath, key string) (string, error) {
	v, ok := values[key]
	if !ok {
		return "", fmt.Errorf("%s: values.%s is missing", recordPath, key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s: values.%s has type %T, expected string", recordPath, key, v)
	}
	if s == "" {
		return "", fmt.Errorf("%s: values.%s is empty", recordPath, key)
	}
	return s, nil
}

// StringValueDefault is StringValue with a fallback for records that
// predate the value being recorded.
func StringValueDefault(values map[string]any, recordPath, key, fallback string) (string, error) {
	if _, ok := values[key]; !ok {
		return fallback, nil
	}
	return StringValue(values, recordPath, key)
}

// RecordPath renders the conventional <dir>/.intropy/scaffold.json path
// for a scaffold directory, for error messages.
func RecordPath(dir string) string {
	return filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath))
}

