// parseBlock reads one scaffold record's kind-specific values into the
// component's wiring. The parser owns per-record validation only; every
// cross-component check (topic contract conflicts, port uniqueness)
// stays in Assemble, gated on the component's shape. The registry itself
// — and its parse rules — lives in internal/template so `int adopt` can
// validate new records against the same rules assembly will apply.
func parseBlock(e template.ScaffoldEntry, c *Component) error {
	w, err := template.BlockParsers[e.BlockKind](e.Values, template.RecordPath(e.Path))
	if err != nil {
		return err
	}
	c.Topic = w.Topic
	c.topicContract = w.Contract
	c.Ports = w.Ports
	if len(w.Ports) == 1 {
		c.Port = w.Ports[0]
	}
	c.missingPort = w.MissingPort
	return nil
}

