package template

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

// AdoptOptions configures Adopt. The embedded CreateOptions carries the
// fetch-and-resolve half (template, version, values, sets, prompter
// inputs, library coordinates); adopt adds the target directory and the
// record-only concerns.
type AdoptOptions struct {
	CreateOptions

	// ProjectDir is the existing component root the record is written
	// into. Required; adopt never creates it.
	ProjectDir string

	// DependsOn populates the record's dependsOn. Each Dir must exist
	// relative to ProjectDir.
	DependsOn []DependencyRecord

	// DryRun prints the record and report without writing anything.
	DryRun bool
}

// Adopt writes a scaffold record for an existing component without
// rendering anything: it resolves the template release and values exactly
// as Create would, validates the record against the block parser registry
// system assembly uses, and writes .intropy/scaffold.json. Source files
// are never touched.
func Adopt(ctx context.Context, opts AdoptOptions) error {
	opts.ProjectDir = strings.TrimSpace(opts.ProjectDir)
	if opts.ProjectDir == "" {
		return errors.New("project directory is required")
	}

	p, err := PrepareCreate(ctx, opts.CreateOptions)
	if err != nil {
		return err
	}
	defer p.Cleanup()

	// Adopt records block components and shared libraries only; a system
	// host's record is created by sys create and carries a different
	// payload.
	if role := roleFromLabels(p.Manifest.Metadata.Labels); role == RoleSystemHost {
		return fmt.Errorf("template %q is a system host; its record is created by 'sys create', not adopted", opts.Template)
	}

	recordPath := RecordPath(opts.ProjectDir)

	// The record must parse under the same rules sys create will apply
	// later, or adoption just defers the failure to assembly time.
	if kind := blockKindFromLabels(p.Manifest.Metadata.Labels); kind != "" {
		if err := ValidateBlockRecord(kind, p.Values, recordPath); err != nil {
			return err
		}
	}

	info, err := os.Stat(opts.ProjectDir)
	if err != nil {
		return fmt.Errorf("stat project directory: %w", err)
	}
	if !info.IsDir() {
		return fmt.Errorf("project directory %s is not a directory", opts.ProjectDir)
	}

	if _, err := os.Stat(recordPath); err == nil && !opts.Force {
		return fmt.Errorf("%s already exists (use --force to overwrite)", recordPath)
	} else if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("stat %s: %w", recordPath, err)
	}

	for _, d := range opts.DependsOn {
		depInfo, err := os.Stat(filepath.Join(opts.ProjectDir, filepath.FromSlash(d.Dir)))
		if err != nil {
			return fmt.Errorf("dependency %s: %w", d.Dir, err)
		}
		if !depInfo.IsDir() {
			return fmt.Errorf("dependency %s is not a directory", d.Dir)
		}
	}

	scaffold := buildScaffold(p.Template, p.Owner, p.Repo, p.Version, p.Values, p.Manifest.Metadata.Labels, opts.DependsOn)

	if opts.DryRun {
		data, err := json.MarshalIndent(scaffold, "", "  ")
		if err != nil {
			return err
		}
		fmt.Fprintf(opts.Stdout, "%s\n", data)
		printAdoptReport(opts.Stderr, opts.ProjectDir, scaffold, true)
		return nil
	}

	if err := WriteScaffold(opts.ProjectDir, scaffold); err != nil {
		return err
	}
	printAdoptReport(opts.Stderr, opts.ProjectDir, scaffold, false)
	return nil
}

// printAdoptReport summarizes the adopted record on stderr: where it came
// from, what it carries, and the drift hints a pre-template component
// should be checked against.
func printAdoptReport(w io.Writer, projectDir string, s Scaffold, dryRun bool) {
	if w == nil {
		return
	}
	action := "adopted"
	if dryRun {
		action = "would adopt"
	}
	fmt.Fprintf(w, "%s %s as %s/%s@%s (template %s)\n", action, projectDir, s.Owner, s.Repo, s.Version, s.Template)

	keys := make([]string, 0, len(s.Values))
	for k := range s.Values {
		keys = append(keys, k)
	}
	sortStrings(keys)
	for _, k := range keys {
		fmt.Fprintf(w, "  %s: %v\n", k, s.Values[k])
	}
	for _, d := range s.DependsOn {
		fmt.Fprintf(w, "  depends on %s at %s\n", d.Template, d.Dir)
	}

	for _, hint := range driftHints(projectDir, s) {
		fmt.Fprintf(w, "warning: %s\n", hint)
	}
	fmt.Fprintln(w, "note: source files were not touched; 'int create --with-docs' scaffolding for existing projects is not available yet")
}

// driftHints checks the record against what is actually on disk. These
// are warnings, never failures: the record is the source of truth going
// forward, and the hints name where the pre-template code disagrees.
func driftHints(projectDir string, s Scaffold) []string {
	var hints []string

	if name, ok := s.Values["projectName"].(string); ok && name != "" {
		if !hasCsproj(projectDir, name) {
			hints = append(hints, fmt.Sprintf("no %s.csproj found under %s — the record's projectName does not match any project file; system assembly will reference a project that is not there", name, projectDir))
		}
	}

	for _, d := range s.DependsOn {
		dir := filepath.Join(projectDir, filepath.FromSlash(d.Dir))
		if !dirHasCsproj(dir) {
			hints = append(hints, fmt.Sprintf("dependency dir %s contains no .csproj — check the dependsOn path", d.Dir))
		}
	}

	if appID, ok := s.Values["appId"].(string); ok && appID != "" {
		hints = append(hints, fmt.Sprintf("verify the Dapr app-id in the component's configuration matches the record's appId %q", appID))
	}

	return hints
}

// hasCsproj reports whether a file named <name>.csproj exists anywhere
// under root.
func hasCsproj(root, name string) bool {
	want := name + ".csproj"
	found := false
	_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || found {
			return nil
		}
		if d.IsDir() && listSkipDirs[d.Name()] {
			return fs.SkipDir
		}
		if !d.IsDir() && d.Name() == want {
			found = true
		}
		return nil
	})
	return found
}

// dirHasCsproj reports whether any .csproj exists directly in dir.
func dirHasCsproj(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".csproj") {
			return true
		}
	}
	return false
}

func sortStrings(s []string) {
	for i := 1; i < len(s); i++ {
		for j := i; j > 0 && s[j] < s[j-1]; j-- {
			s[j], s[j-1] = s[j-1], s[j]
		}
	}
}

