package template

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const adoptExtractorYAML = `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: extractor
  title: Extractor
  labels:
    intropy.dev/block-kind: extractor
    intropy.dev/data-flow: in
spec:
  parameters:
    type: object
    required: [name, topic, contract, appId, projectName]
    properties:
      name:
        type: string
      organization:
        type: string
      topic:
        type: string
      contract:
        type: string
      pubsub:
        type: string
        default: pubsub
      appId:
        type: string
      projectName:
        type: string
      port:
        type: string
`

const adoptHostYAML = `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: system-host
  title: System Host
  labels:
    intropy.dev/template-role: system-host
spec:
  parameters:
    type: object
    properties:
      name:
        type: string
`

// newAdoptServer serves a tarball with an extractor template and a
// system-host template, laid out as the v1 model expects.
func newAdoptServer(t *testing.T, tag string) *httptest.Server {
	t.Helper()
	tarball := buildTarGz(t, "owner-repo-abc123", map[string]string{
		"extractor/template.yaml":      adoptExtractorYAML,
		"extractor/skeleton/dummy.txt": "skeleton\n",
		"system-host/template.yaml":    adoptHostYAML,
		"system-host/skeleton/dummy":   "skeleton\n",
	})
	mux := http.NewServeMux()
	mux.HandleFunc("/repos/o/r/releases/latest", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"tag_name":"` + tag + `"}`))
	})
	mux.HandleFunc("/repos/o/r/tarball/"+tag, func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write(tarball)
	})
	return httptest.NewServer(mux)
}

func adoptValues() map[string]any {
	return map[string]any{
		"name":        "Extractor.Perfion",
		"topic":       "product-export",
		"contract":    "ExportEvent",
		"appId":       "product-distribution-extractor-perfion",
		"projectName": "Extractor.Perfion",
		"port":        "perfion-extractor-source",
	}
}

func adoptOpts(srv *httptest.Server, dir string) AdoptOptions {
	return AdoptOptions{
		CreateOptions: CreateOptions{
			Template:      "extractor",
			Version:       "v1.2.3",
			SetValues:     adoptValues(),
			NoInput:       true,
			HTTP:          srv.Client(),
			Owner:         "o",
			Repo:          "r",
			GitHubBaseURL: srv.URL,
		},
		ProjectDir: dir,
	}
}

func readAdoptedRecord(t *testing.T, dir string) Scaffold {
	t.Helper()
	s, err := LoadScaffold(filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath)))
	if err != nil {
		t.Fatalf("load scaffold: %v", err)
	}
	return *s
}

func TestAdoptWritesRecord(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "Extractor.Perfion.csproj"), []byte("<Project/>"), 0o644); err != nil {
		t.Fatal(err)
	}
	var stdout, stderr bytes.Buffer
	opts := adoptOpts(srv, dir)
	opts.Stdout = &stdout
	opts.Stderr = &stderr

	if err := Adopt(context.Background(), opts); err != nil {
		t.Fatalf("Adopt: %v", err)
	}

	got := readAdoptedRecord(t, dir)
	if got.SchemaVersion != ScaffoldSchemaVersion {
		t.Errorf("SchemaVersion = %d", got.SchemaVersion)
	}
	if got.Template != "extractor" {
		t.Errorf("Template = %q", got.Template)
	}
	if got.Owner != "o" || got.Repo != "r" {
		t.Errorf("Owner/Repo = %q/%q", got.Owner, got.Repo)
	}
	if got.Version != "v1.2.3" {
		t.Errorf("Version = %q", got.Version)
	}
	if got.BlockKind != BlockKindExtractor || got.DataFlow != "in" {
		t.Errorf("BlockKind/DataFlow = %q/%q", got.BlockKind, got.DataFlow)
	}
	if got.Values["name"] != "Extractor.Perfion" {
		t.Errorf("values[name] = %v", got.Values["name"])
	}
	if got.Values["pubsub"] != "pubsub" {
		t.Errorf("values[pubsub] = %v (default should layer in)", got.Values["pubsub"])
	}
	if stdout.Len() != 0 {
		t.Errorf("stdout should be empty on write, got %q", stdout.String())
	}
	if !strings.Contains(stderr.String(), "adopted") {
		t.Errorf("stderr should carry the report, got %q", stderr.String())
	}
	if strings.Contains(stderr.String(), "warning:") {
		t.Errorf("matching csproj should produce no drift warning, got %q", stderr.String())
	}
}

func TestAdoptDryRunWritesNothing(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	dir := t.TempDir()
	var stdout, stderr bytes.Buffer
	opts := adoptOpts(srv, dir)
	opts.Stdout = &stdout
	opts.Stderr = &stderr
	opts.DryRun = true

	if err := Adopt(context.Background(), opts); err != nil {
		t.Fatalf("Adopt: %v", err)
	}

	if _, err := os.Stat(filepath.Join(dir, filepath.FromSlash(ScaffoldRelPath))); !os.IsNotExist(err) {
		t.Errorf("dry-run must not write the record, stat err = %v", err)
	}
	var got Scaffold
	if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
		t.Fatalf("stdout should be the record JSON: %v\n%s", err, stdout.String())
	}
	if got.Template != "extractor" || got.Version != "v1.2.3" {
		t.Errorf("record = %+v", got)
	}
	if !strings.Contains(stderr.String(), "would adopt") {
		t.Errorf("stderr report should say 'would adopt', got %q", stderr.String())
	}
}

func TestAdoptExistingRecordRequiresForce(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	dir := t.TempDir()
	existing := Scaffold{SchemaVersion: ScaffoldSchemaVersion, Template: "old"}
	if err := WriteScaffold(dir, existing); err != nil {
		t.Fatal(err)
	}

	var stderr bytes.Buffer
	opts := adoptOpts(srv, dir)
	opts.Stderr = &stderr
	err := Adopt(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "already exists") {
		t.Fatalf("err = %v, want 'already exists'", err)
	}

	opts.Force = true
	if err := Adopt(context.Background(), opts); err != nil {
		t.Fatalf("Adopt --force: %v", err)
	}
	if got := readAdoptedRecord(t, dir); got.Template != "extractor" {
		t.Errorf("Template = %q after --force", got.Template)
	}
}

func TestAdoptMissingRequiredValueNamesKey(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	values := adoptValues()
	delete(values, "contract")

	opts := adoptOpts(srv, t.TempDir())
	opts.SetValues = values
	opts.Stderr = &bytes.Buffer{}
	err := Adopt(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "contract") {
		t.Fatalf("err = %v, want missing 'contract' named", err)
	}
}

func TestAdoptValidationGateRejectsBadRecord(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	// All required template parameters are present, but contract is not a
	// string — schema-valid, record-invalid. The gate must fail with the
	// same guidance sys create would give.
	values := adoptValues()
	values["contract"] = 42

	opts := adoptOpts(srv, t.TempDir())
	opts.SetValues = values
	opts.Stderr = &bytes.Buffer{}
	err := Adopt(context.Background(), opts)
	if err == nil {
		t.Fatal("expected validation gate error")
	}
	if !strings.Contains(err.Error(), "add \"contract\"") {
		t.Errorf("err should carry the contract guidance, got: %v", err)
	}
}

func TestAdoptDependsOn(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	dir := t.TempDir()
	shared := filepath.Join(dir, "shared")
	if err := os.MkdirAll(shared, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(shared, "Acme.Shared.csproj"), []byte("<Project/>"), 0o644); err != nil {
		t.Fatal(err)
	}

	opts := adoptOpts(srv, dir)
	opts.Stderr = &bytes.Buffer{}
	opts.DependsOn = []DependencyRecord{{Template: "shared-contracts", Dir: "shared"}}
	if err := Adopt(context.Background(), opts); err != nil {
		t.Fatalf("Adopt: %v", err)
	}
	got := readAdoptedRecord(t, dir)
	if len(got.DependsOn) != 1 || got.DependsOn[0].Template != "shared-contracts" || got.DependsOn[0].Dir != "shared" {
		t.Errorf("DependsOn = %+v", got.DependsOn)
	}
}

func TestAdoptDependsOnMissingDir(t *testing.T) {
	srv := newAdoptServer(t, "v1.2.3")
	defer srv.Close()

	opts := adoptOpts(srv, t.TempDir())
	opts.Stderr = &bytes.Buffer{}
	opts.DependsOn = []DependencyRecord{{Template: "shared-contracts", Dir: "../nope"}}
	err := Adopt(context.Background(), opts)
	if err == nil || !strings.Contains(err.Error(), "../nope") {
		t.Fatalf("err = %v, want the missing dir named", err)
	}
}

func TestAdoptSystemHostRefused(t *testing.T) {
