package main

import (
	"bytes"
	"errors"
	"strings"
	"testing"
)

func TestParseDependsOn(t *testing.T) {
	t.Run("valid entry", func(t *testing.T) {
		deps, err := parseDependsOn([]string{"shared-contracts:../shared"})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if len(deps) != 1 || deps[0].Template != "shared-contracts" || deps[0].Dir != "../shared" {
			t.Errorf("deps = %+v", deps)
		}
	})

	t.Run("repeatable", func(t *testing.T) {
		deps, err := parseDependsOn([]string{"a:../a", "b:../b"})
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if len(deps) != 2 {
			t.Errorf("deps = %+v", deps)
		}
	})

	t.Run("malformed entries are usage errors", func(t *testing.T) {
		for _, item := range []string{"no-colon", ":dir-only", "template:", "a:b:c"} {
			_, err := parseDependsOn([]string{item})
			if err == nil {
				t.Errorf("%q: expected error, got nil", item)
				continue
			}
			var ue *usageError
			if !errors.As(err, &ue) {
				t.Errorf("%q: error %v is not a usageError", item, err)
			}
		}
	})
}

func TestIntAdoptArgs(t *testing.T) {
	reset := func(t *testing.T) {
		t.Helper()
		intAdoptFlags = adoptFlags{}
		t.Cleanup(func() { intAdoptFlags = adoptFlags{} })
	}

	t.Run("missing template arg", func(t *testing.T) {
		reset(t)
		if err := intAdoptCmd.Args(intAdoptCmd, nil); err == nil {
			t.Fatal("expected ExactArgs error, got nil")
		}
	})

	t.Run("-n with -s name= conflict is a usage error", func(t *testing.T) {
		reset(t)
		intAdoptFlags.name = "foo"
		intAdoptFlags.sets = []string{"name=bar"}
		var stdout, stderr bytes.Buffer
		intAdoptCmd.SetOut(&stdout)
		intAdoptCmd.SetErr(&stderr)

		err := intAdoptCmd.RunE(intAdoptCmd, []string{"extractor"})
		if err == nil {
			t.Fatal("expected error, got nil")
		}
		var ue *usageError
		if !errors.As(err, &ue) {
			t.Errorf("error %v is not a usageError", err)
		}
	})

	t.Run("malformed --depends-on is a usage error before any fetch", func(t *testing.T) {
		reset(t)
		intAdoptFlags.dependsOn = []string{"broken"}
		var stdout, stderr bytes.Buffer
		intAdoptCmd.SetOut(&stdout)
		intAdoptCmd.SetErr(&stderr)

		err := intAdoptCmd.RunE(intAdoptCmd, []string{"extractor"})
		if err == nil {
			t.Fatal("expected error, got nil")
		}
		var ue *usageError
		if !errors.As(err, &ue) {
			t.Errorf("error %v is not a usageError", err)
		}
		if !strings.Contains(err.Error(), "broken") {
			t.Errorf("error should name the bad flag value, got %v", err)
		}
	})
}

package system

import (
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// TestAssembleAdoptedRecord proves the adoption loop: a record written for
// a pre-template component (the record-only half of `int adopt`, run here
// against a fixture so no template fetch is needed) assembles into a
// component with the wiring sys create generates code from.
func TestAssembleAdoptedRecord(t *testing.T) {
	workspace := t.TempDir()
	componentDir := workspace + "/Extractor.Perfion"

	record := template.Scaffold{
		SchemaVersion: template.ScaffoldSchemaVersion,
		Template:      "extractor",
		Owner:         "integrio-intropy",
		Repo:          "intropy-templates",
		Version:       "v1.2.3",
		Values: map[string]any{
			"name":        "Extractor.Perfion",
			"organization": "maxbo",
			"topic":       "product-export",
			"contract":    "ExportEvent",
			"pubsub":      "pubsub",
			"appId":       "product-distribution-extractor-perfion",
			"projectName": "Extractor.Perfion",
			"port":        "perfion-extractor-source",
		},
		BlockKind: template.BlockKindExtractor,
		DataFlow:  "in",
		DependsOn: []template.DependencyRecord{{Template: "shared-contracts", Dir: "../shared"}},
	}
	if err := template.WriteScaffold(componentDir, record); err != nil {
		t.Fatal(err)
	}

	// The adopted record must pass the same validation gate adopt applies.
	if err := template.ValidateBlockRecord(record.BlockKind, record.Values, template.RecordPath(componentDir)); err != nil {
		t.Fatalf("ValidateBlockRecord: %v", err)
	}

	entries, warnings := template.ListScaffolds(workspace)
	if len(warnings) != 0 {
		t.Fatalf("scan warnings: %v", warnings)
	}

	var warnMsgs []string
	model, err := Assemble(entries, func(format string, args ...any) {
		warnMsgs = append(warnMsgs, format)
	})
	if err != nil {
		t.Fatalf("Assemble: %v", err)
	}

	if len(model.Components) != 1 {
		t.Fatalf("components = %+v, want exactly one", model.Components)
	}
	c := model.Components[0]
	if c.AppID != "product-distribution-extractor-perfion" {
		t.Errorf("AppID = %q", c.AppID)
	}
	if c.Kind != template.BlockKindExtractor {
		t.Errorf("Kind = %q", c.Kind)
	}
	if c.Topic == nil || c.Topic.Name != "product-export" || c.Topic.Pubsub != "pubsub" {
		t.Errorf("Topic = %+v", c.Topic)
	}
	if c.Port != "perfion-extractor-source" || len(c.Ports) != 1 {
		t.Errorf("Port/Ports = %q/%v", c.Port, c.Ports)
	}
	if len(model.Topics) != 1 || model.Topics[0].Contract != "ExportEvent" {
		t.Errorf("Topics = %+v", model.Topics)
	}
}

